DO $$ BEGIN CREATE TEMP TABLE IF NOT EXISTS _p AS SELECT DISTINCT po.* FROM supplier_invoices s CROSS JOIN LATERAL (SELECT public._sinv_po(s) AS po_id) x JOIN purchase_orders po ON po.id = x.po_id WHERE po.job_id IS NULL; RAISE EXCEPTION 'PROBE3 %', (SELECT string_agg(t,'|') FROM (SELECT extract(year FROM ordered_at)||'='||count(*) t FROM _p GROUP BY extract(year FROM ordered_at) ORDER BY 1) z); END $$;
